import {getDocumentDraftOwner} from './material-navigation.js';
import {differenceMarkup, valueMarkup, valueEditor, collectEditedValue, provenanceMarkup} from './collaboration.js';
import {showEvidence} from './evidence-viewer.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const words=v=>String(v??'').replaceAll('_',' ').toLowerCase().replace(/^./,c=>c.toUpperCase());
const labels={retry:'Retry retrieval',manual:'Supply original',candidate_accept:'Register candidate',candidate_reject:'Reject candidate',task_defer:'Keep pending',replacement_accept:'Accept replacement',replacement_reject:'Reject replacement',qa:'Record inspection result'};
const link=(url,label)=>{try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?`<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:''}catch{return ''}};
const button=(command,label,extra='')=>`<button type="button" data-source-command="${command}" ${extra}>${label}</button>`;
const scoreNames={authority_quality:'Authority',scope_relevance:'Scope relevance',version_currency:'Version currency',traceability:'Traceability',access_permission:'Access permission'};
const version=s=>s.version||s.version_label||s.publication_date||s.effective_date||s.last_modified||'Not recorded';
const dateVersion=value=>/^\d{4}-\d{2}-\d{2}(?:[T ].*)?$/.test(value)||/^\d{2}[.\/-]\d{2}[.\/-]\d{2}(?:\d{2})?$/.test(value);
